// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 newVal, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(newVal != 1 ether); // distinct from the initial MinSum so a change is observable

        // Before initialization, SetMinSum is allowed and sets MinSum.
        vm.prank(actor);
        try c.SetMinSum(newVal) { /* allowed pre-init */ } catch { revert("pre-init SetMinSum must succeed"); }
        require(c.MinSum() == newVal, "pre-init set failed");

        // Initialize permanently.
        vm.prank(actor);
        c.Initialized();

        // After initialization, SetMinSum must revert and MinSum must stay newVal.
        bool ok;
        vm.prank(actor);
        try c.SetMinSum(newVal + 1) { ok = true; } catch { ok = false; }

        assertTrue(!ok && c.MinSum() == newVal);
    }
}

