pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    LogFile log;

    function setUp() public {
        c = new C();
        log = new LogFile();
    }

    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(log));
        vm.prank(actor);
        c.SetLogFile(address(log));

        vm.deal(actor, uint256(amount));
        vm.prank(actor);
        c.Deposit{value: uint256(amount)}();

        (address sender,,, uint val) = log.History(0);
        assertTrue(sender == actor && val == uint256(amount), "deposit must be logged in the configured LogFile");
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

